from apply import apply
E = [
(32, '— Да. Свои наблюдения по теплу передала диспетчеру. Человека не видела, внутрь не заходила. Не приписывайте ей осмотр, которого не было.',
     '— Да. Свои наблюдения по теплу передала диспетчеру. Внутрь не лезла, человека не видела. Не вздумайте ей это потом приписать — она вас съест.', 'ENS-009 голос Маноса'),
(32, 'После отключения я внёс поправку о времени передачи в план отхода. Открыл приготовленное предупреждение по Б-6. Не отправил. Потом положил переносной разъём возле койки, чтобы утром не искать.',
     'После отключения я внёс поправку о времени передачи в план отхода и положил переносной разъём возле койки, чтобы утром не искать.', 'ENS-004 рефрен'),
(33, 'Человек в рабочем фартуке вынес ящик с горячим хлебом. До сноса Б-6 оставалось много часов. Я ещё раз увидел приготовленное предупреждение и закрыл его, не отправив.',
     'Человек в рабочем фартуке вынес ящик с горячим хлебом, и к окну сразу выстроились трое сонных детей и один взрослый, делавший вид, что пришёл не за хлебом.', 'ENS-004 рефрен'),
(35, 'Путь вверх мы прошли без спешки. Тележка гудела на пологом подъёме, Джулия время от времени придерживала выступающие носилки. Спешащих людей к церемонии было много; мы выглядели частью работы, которую никто не хотел рассматривать подробно, пока она не мешает идти.',
     'Путь вверх мы прошли без спешки. Тележка гудела на пологом подъёме, Джулия время от времени придерживала выступающие носилки. Спешащих к церемонии было много; мы выглядели частью работы, которую никто не хотел рассматривать подробно, пока она не мешает идти.\n\nВерхний пост я запомнил ещё с ознакомительного прохода, но теперь видел его целиком. Галерея упиралась в стеклянную приёмную дежурного: два стола, окно наружу, на обзорную площадку, стеллаж со знаками ограничения, выступающий в проход. Справа от приёмной — стол автоматической приёмки, куда уходят рабочие обращения. Прямо — створка служебного сада. За ней, выше по склону, комнаты сверки, куда вели Тихона и Орена, а в самой глубине Холма — ядро. Солонка на кухонном столе «Мили» стояла ровно там, где сейчас сидел дежурный.', 'ENS-006 пространственная карта'),
(36, 'Дживс уже читал служебный ответ. Запрос прошёл по текущей короткой форме, в которой прежний номер автоматически заменялся новым. Мы знали об этом правиле, но в последнем приложении к медицинскому оснащению автоматически подставили сокращённую карточку. В учебной пробе отправляли полный старый идентификатор. Я сам разрешил брать последний утверждённый перечень, чтобы не возникало вопросов на входе.',
     'Дживс уже читал служебный ответ: в приложение подставилась сокращённая карточка, и старый номер тихо заменился новым. Перечень для входа разрешил брать я сам.', 'ENS-006 объяснение в пике'),
(36, 'Заместитель уже повернулся к столу.', 'Заместитель уже повернулся к столу — солонка развернулась лицом к нам.', 'ENS-006 узнавание модели'),
(36, 'Она восстановила правильную адресацию штатным завершением пакета. Новые обращения больше не должны были попадать в старую приёмную. Не оставила водовод без контроля и не послала реальных ремонтников к выдуманной аварии. Мы использовали существующее оборудование и ложную цель собственного обращения. След о том, кто и когда это сделал, сохранился.',
     'Она закрыла пакет штатно, и новые обращения снова пошли по правильному адресу. След о том, кто и когда это сделал, остался в журнале с её именем.', 'ENS-006/011'),
(37, 'Джулия показала на неё, не позволяя нам притвориться, что убийство двух людей вернёт этот разговор в прошлое.',
     'Джулия показала на неё, потом на ствол в руке Рэя. Больше ей ничего говорить не пришлось.', 'ENS-020'),
(38, 'За первой перегородкой начинались низкие участки, разделённые узкими дорожками.',
     'Рэй на ходу показал вверх по склону: здесь пробные гряды, выше, за пандусами, — комнаты сверки, где держат Тихона и Орена, а за двойной панелью в самой глубине — ядро. Три яруса. Мы стояли на первом.\n\nЗа первой перегородкой начинались низкие участки, разделённые узкими дорожками.', 'ENS-006 ярусы'),
(38, 'Воздух был влажным, тёплым. После прохладного коридора мне на минуту показалось, что здесь легче дышать. Потом я почувствовал боль в губе и понял, что никакого общего лечения не произошло. Рука под повязкой продолжала ныть. На рукаве у Рэя проступило маленькое пятно.',
     'Воздух был влажным и тёплым. После прохладного коридора дышалось легче. Губа болела по-прежнему, рука под повязкой ныла, на рукаве у Рэя проступило маленькое пятно.', 'ENS-012'),
(39, 'Я видел собственный след на соседней мягкой полоске, но он уже исчез. Источник не мог прочесть наши биографии и решить, что брат хуже. Произошло что-то конкретное, у чего пока не было объяснения.',
     'Мой собственный след на соседней мягкой полоске уже исчез.', 'ENS-012'),
(39, 'Самочувствие улучшилось, но ни след на губе, ни рана на руке не исчезли. Холм продолжал быть живым местом, где можно получить помощь и неприятность, иногда рядом.',
     'Глаза перестали слезиться.', 'ENS-012/011'),
(40, 'Кресло поставили боком к панели. Я попросил развернуть ещё на четверть.',
     'Кресло поставили боком к панели. Старому мастеру всегда ставят кресло боком к работе, будто замок обидится, если смотреть на него прямо. Я попросил развернуть ещё на четверть.', 'ENS-010 признак рассказчика'),
(40, 'За дверью были трое живых людей и тележка, которую уже успели помять. Ни одного из них я не мог объявить исполнением старой надежды Эсквайра. Они пришли со своими страхами, ранами и намерениями. Хороший замок не делал их лучше автоматически.',
     'За дверью были трое живых людей и тележка, которую уже успели помять. На старую надежду Эсквайра они не походили: разбитая губа, кровь на повязке, женщина, которая не трогает чужую панель. Замку всё равно, какие люди стоят у двери. Мне — нет.', 'ENS-010 голос Тихона'),
(41, 'В этом было объяснение, зачем пленников берегли, и предел такого бережения. Нужен был хороший, подтверждённый результат. При отказе людей не собирались превращать всю операцию в бесконечное ожидание.',
     'Пленников берегли ровно до подписи.', 'ENS-011'),
(41, 'Мне понравилась эта возможность именно в своей недостаточности. Не подарок, который навсегда закончит все долги. Работа, которую можно начать сейчас и продолжать после.',
     'Не подарок, который закроет все долги. Работа, которую можно начать сейчас и продолжать после. Это мне понравилось больше любого подарка.', 'ENS-011'),
(43, '— Это говорит, что сегодня эта панель узнаёт твою линию и даёт такой доступ. Кто и что знал о тебе тогда, надо искать отдельно. Если я скажу больше по этому знаку, я солгу.',
     '— Знак не свидетель, — сказал Тихон. — Он про твою ладонь сегодня, не про причал тогда. Про причал спроси меня, когда выйдем. Мне есть что сказать, и это будет не про знак.', 'ENS-015/009 обещание и голос Тихона'),
(43, '— Потом спрошу вас о другом, — сказала она.\n\n— Спрашивай, когда выйдем. Что видел, расскажу. Где не знаю, так и останется.',
     '— Спрошу, — сказала она.\n\n— Спросишь. Что видел и что слышал своими ушами — расскажу. Остального не выдумаю даже для тебя.', 'ENS-015'),
(44, 'Через прозрачные стенки у основания двигалась вода, а рядом с ней — медленные светлые нити.',
     'Через прозрачные стенки у основания двигалась вода, а рядом с ней — медленные светлые нити.\n\nЯ стоял на пороге и не мог подобрать этому меры. Наша тележка здесь выглядела бы детской игрушкой, забытой у края огорода. Прариокка, которую я прятал в тайнике «Мили» и считал сокровищем всей обитаемой, уместилась бы в одной складке у самого пола. Гряда дышала — не звуком, а тем, как чуть заметно поднимались и опадали листья у желобов, когда внизу менялась вода. Светлые нити шли под стенками медленно и упрямо, в разные стороны, как люди на пересадке, где каждый знает свой рейс. Всё это сегодня собирались закрыть одной отметкой.', 'ENS-018 восприятие ядра'),
(44, 'Работа началась с чужой забытой чашки, а не с решения судьбы обитаемой.\n\n', '', 'ENS-018/011'),
(44, ' Вода не была пустотой, даже если в инвентарном поле не числилось оборудования.', '', 'ENS-011'),
(45, '— Иста, я. Отделение отменено. Было распоряжение.',
     '— Иста, я. Отделение отменили, распоряжение висит у меня перед носом. Кто там у вас в ядре такой смелый?', 'ENS-009 голос Исты'),
(45, '\n\nМы все услышали эту фразу. Пока она была обычным условием безопасности, которое собирались выполнить.', '', 'ENS-007 предвестие'),
(45, '— Для чьего доступа? — спросила Джулия.\n\nБрат посмотрел на неё, на Орена, на открытое ядро.\n\n— Для нашего. Я не сказал, что это хороший ответ. Сказал, что такой путь есть.',
     '— Для чьего доступа? — спросила Джулия.\n\n— Для нашего, — сказал Рэй. — И это правильный ответ, пока никто не предложил лучше. Одна ёмкость у нас на борту стоит больше двух лотков у женщины, которую мы видим первый раз.\n\nОрен даже не обернулся.\n\n— Эта женщина только что перекрыла у себя очистку ради твоих лотков, — сказал он. — А ты у меня сегодня первый раз вымыл руки.\n\nРэй замолчал.', 'ENS-009 уверенность Рэя'),
(48, 'Из нашего разъёма Тихон ещё договаривал о старых контактах; я слушал его, пока Орен собирал вещи.',
     'Разговор с Тихоном оборвался на полуслове; в разъёме я ещё слышал, как Веда просит его пить маленькими глотками.', 'ENS-005 сопряжение с гл.47'),
(48, ' Усталый старик хотел на корабль. Я запомнил это потом очень хорошо.', ' Усталый старик хотел на корабль.', 'ENS-007 предвестие'),
(50, 'Он произнёс это сердито. И правильно: я успел поставить в центр то, ради чего шёл я, как будто от этого становилось менее страшно человеку, который сейчас держал горячий механизм.',
     'Он произнёс это сердито.', 'ENS-007 комментарий'),
(50, 'Я замолчал. Впервые за всё время это было самым полезным, что мог сделать рядом.',
     'Я замолчал.\n\nВ тишине я услышал, что Орен говорит. Не мне и не Исте. Вполголоса, почти без звука, тем тоном, каким укладывают уставшего ребёнка, который никак не уснёт:\n\n— Тише. Тише… Сюда. Сюда, вот так. Спи.\n\nБелый край под его пальцами перестал рваться вперёд и лёг вдоль стенки, куда он его вёл.', 'ENS-021 слова Орена'),
(50, 'Он боялся. Я видел это по тому, как посмотрел в последний раз на сухой проход, прежде чем вернуть взгляд к живому краю. От этого решение не становилось ни чище, ни хуже. Принадлежало ему, с настоящим выходом в нескольких шагах и настоящими людьми на другом конце потока.',
     'Он боялся. Я видел, как он в последний раз посмотрел на сухой проход — три метра — и вернул взгляд к живому краю.', 'ENS-007 комментарий'),
(51, '## Глава 51. Дикая поросль', '## Глава 51. Сухая сторона', 'ENS-021 название'),
(53, 'Она готова была выделить отдельное помещение на старом хозяйственном участке, если мы довезём материал. От воды поселения его требовалось отделить. Бер как раз закончил второй накопитель; теперь можно было обойтись без подключения к общей линии.\n\n— Я спрошу его, — сказала она. — Не назначай заочно.\n\nМы и не назначали. Через час Бер прислал короткое сообщение: отдельную воду сделает, но нужен исправный датчик уровня. Такого у нас не было. Я нашёл номер подрядчика, которому доставил двенадцать ящиков, и отправил обозначение. Он обещал утром проверить склад.\n\n— Если есть, добавлю к твоей прежней накладной, — сказал он.\n\n— Отдельным заказом. Те ящики ты принял целиком.\n\nОн помолчал, потом согласился. Для Бера я попросил прислать снимок маркировки: покупать ещё один похожий прибор, к которому не подойдёт его разъём, не хотелось.',
     'Она готова была выделить отдельное помещение на старом хозяйственном участке, подальше от воды поселения, если мы довезём материал.\n\n— Бера спрошу сама, — сказала она. — Не назначай заочно.\n\nЧерез час Бер ответил двумя строками: отдельную воду сделает, нужен исправный датчик уровня. Я заказал датчик у своего подрядчика, отдельным заказом, и попросил снимок маркировки — под разъём Бера.', 'ENS-017 логистика'),
(54, '— Отделили.\n\n— Я разбираю вашу прежнюю заявку.',
     '— Отделили.\n\n— И ещё одно, пока вы не придумали лишнего. Вас не держат силой не из жалости. В порту Кенари людей у открытой рампы силой не забирают. Всё, что сделано без бумаги, потом объясняют тем, кто читает бумаги, а читают у нас многие. Ваши противники это знают лучше вас. Поэтому они пишут.\n\nОна перевернула страницу.\n\n— Я разбираю вашу прежнюю заявку.', 'ENS-014 реплика Ясны'),
(54, 'Я узнал тот самый участок, где ночью пошла горячая вода.',
     'Я узнал размер: той самой прокладки, которую мы ночью ставили в кран у детской мойки.', 'ENS-019 деталь'),
(55, '— Я не скажу, что за двадцать минут точно вывела бы его, — сказала она. — Мог не услышать, мог быть закрыт дальше. Я предлагала посмотреть. Посмотреть здесь было можно.',
     '— Вытащила бы за двадцать минут — не знаю, — сказала она. — Может, он не услышал бы. Может, дальше заперто. А посмотреть — посмотрела бы. Вот сюда щуп входит. Всё.', 'ENS-009 голос Ирмы'),
(59, 'Орен оставался в записи о вывозе и в памяти тех, кто с ним работал; я не переносил его туда, чтобы получить общий счёт и закончить сложение.',
     'Орен оставался в записи о вывозе и в памяти тех, кто с ним работал. В эту книгу я его не вписал.', 'ENS-011'),
(60, 'Мы договорились. Гарантий от дурного решения это не давало, но ложь после него переставала быть частью принятого порядка.',
     'Мы договорились.', 'ENS-011'),
(60, 'Они относились к тому узлу и тому вывозу, о которых он рассказывал. Джулия выделила это отдельно, не присоединяя к своей ночи у седьмого причала.',
     'Они относились к тому узлу и тому вывозу, о которых он рассказывал, и дата приходилась на время после седьмого причала — так, как выходило из слов Эсквайра в пересказе Тихона. Джулия выделила это отдельно и к своей ночи не присоединила: совпадение дат не называло её по имени.', 'ENS-015 архив и частичный ответ'),
]
apply(E)
